"import os
import json

log_dir = r"C:\Users\NANDHA A\.gemini\antigravity-ide\brain\1237cb3f-efd0-4a57-b440-f74287d1898a\.system_generated\logs"
log_path = os.path.join(log_dir, "transcript.jsonl")

if os.path.exists(log_path):
    print("Transcript found! Searching...")
    with open(log_path, "r", encoding="utf-8") as f:
        for i, line in enumerate(f):
            if "ensure_sound_effects" in line or "_health_toast_loop" in line:
                print(f"Line {i+1} matches!")
                try:
                    data = json.loads(line)
                    # Print preview of the content
                    content = str(data.get("content", ""))[:200]
                    print(f"  Type: {data.get('type')}, Content preview: {content}")
                except Exception as e:
                    print(f"  Error parsing JSON: {e}")
else:
    print(f"Transcript not found at {log_path}")
